xpath.script:
document.addEventListener('DOMContentLoaded', function() {
    var cartEl = document.querySelector('.o_wsale_my_cart');
    if (!cartEl) return;

    var popover = null;
    var hideTimeout = null;
    var isPopoverHovered = false;

    function showPopover() {
        if (popover) return;

        fetch('/shop/cart/popover', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {} })
        })
        .then(function(response) { return response.json(); })
        .then(function(data) {
            if (data && data.result && data.result.html) {
                createPopover(data.result.html);
            }
        })
        .catch(function(err) { console.error('Cart popover error:', err); });
    }

    function createPopover(content) {
        if (popover) popover.dispose();

        var linkEl = cartEl.querySelector('a') || cartEl;
        popover = new bootstrap.Popover(linkEl, {
            trigger: 'manual',
            placement: 'bottom',
            html: true,
            content: content,
            customClass: 'mycart-popover',
            container: 'body',
            sanitize: false
        });
        popover.show();

        setTimeout(function() {
            var popoverEl = document.querySelector('.mycart-popover');
            if (popoverEl) {
                popoverEl.addEventListener('mouseenter', function() {
                    isPopoverHovered = true;
                    clearTimeout(hideTimeout);
                });
                popoverEl.addEventListener('mouseleave', function() {
                    isPopoverHovered = false;
                    hideTimeout = setTimeout(hidePopover, 300);
                });
            }
        }, 100);
    }

    function hidePopover() {
        if (popover) {
            popover.dispose();
            popover = null;
        }
        isPopoverHovered = false;
    }

    cartEl.addEventListener('mouseenter', function() {
        clearTimeout(hideTimeout);
        showPopover();
    });

    cartEl.addEventListener('mouseleave', function() {
        hideTimeout = setTimeout(function() {
            if (!isPopoverHovered) hidePopover();
        }, 300);
    });
});
